<?php
/** Primary navigation and mega menu helpers. */
defined( 'ABSPATH' ) || exit;
function nytt01_get_mega_menu_key( $menu_item ) { $classes = array_filter( array_map( 'sanitize_html_class', (array) $menu_item->classes ) ); foreach ( array( 'nytt01-mega-services' => 'services', 'nytt01-mega-about' => 'about', 'nytt01-mega-blog' => 'blog' ) as $class => $key ) { if ( in_array( $class, $classes, true ) ) return $key; } $candidates = array( sanitize_title( wp_strip_all_tags( (string) $menu_item->title ) ) ); if ( ! empty( $menu_item->url ) ) { $path = trim( (string) wp_parse_url( $menu_item->url, PHP_URL_PATH ), '/' ); if ( $path ) $candidates[] = sanitize_title( basename( $path ) ); } foreach ( array_unique( $candidates ) as $candidate ) { if ( in_array( $candidate, array( 'services', 'service' ), true ) ) return 'services'; if ( in_array( $candidate, array( 'about', 'about-us' ), true ) ) return 'about'; if ( in_array( $candidate, array( 'blog', 'news', 'insights' ), true ) ) return 'blog'; } return ''; }
function nytt01_get_navigation_image_uri( $filename ) { return get_theme_file_uri( '/assets/images/navigation/' . ltrim( sanitize_file_name( $filename ), '/' ) ); }
function nytt01_get_services_mega_menu_items() { $items = array( array( 'key' => 'wordpress-design', 'title' => __( 'WordPress Design', 'nolan-young-theme-template-01' ), 'description' => __( 'Clear strategy-led layouts for service businesses that need polish and conversion focus.', 'nolan-young-theme-template-01' ), 'image' => nytt01_get_navigation_image_uri( 'service-1.svg' ), 'url' => home_url( '/services/wordpress-design/' ), 'details' => array( 'IA workshops', 'Wireframes', 'Content planning', 'Responsive systems' ) ), array( 'key' => 'custom-theme', 'title' => __( 'Custom Theme Development', 'nolan-young-theme-template-01' ), 'description' => __( 'Build maintainable WordPress themes with reusable sections and stable markup.', 'nolan-young-theme-template-01' ), 'image' => nytt01_get_navigation_image_uri( 'service-2.svg' ), 'url' => home_url( '/services/custom-theme-development/' ), 'details' => array( 'Templates', 'Components', 'Build tooling', 'Testing' ) ), array( 'key' => 'woocommerce', 'title' => __( 'WooCommerce', 'nolan-young-theme-template-01' ), 'description' => __( 'Conversion-ready store setups that support product merchandising and checkout flow.', 'nolan-young-theme-template-01' ), 'image' => nytt01_get_navigation_image_uri( 'service-3.svg' ), 'url' => home_url( '/services/woocommerce/' ), 'details' => array( 'Catalogs', 'Checkout', 'Payments', 'Emails' ) ), array( 'key' => 'redesign', 'title' => __( 'Website Redesign', 'nolan-young-theme-template-01' ), 'description' => __( 'Modernize an existing site without sacrificing content, SEO, or publishing habits.', 'nolan-young-theme-template-01' ), 'image' => nytt01_get_navigation_image_uri( 'service-4.svg' ), 'url' => home_url( '/services/website-redesign/' ), 'details' => array( 'Audit', 'Migration', 'QA', 'Launch support' ) ), array( 'key' => 'integrations', 'title' => __( 'Integrations & Automation', 'nolan-young-theme-template-01' ), 'description' => __( 'Connect forms, CRMs, email, and reporting with reliable handoffs.', 'nolan-young-theme-template-01' ), 'image' => nytt01_get_navigation_image_uri( 'future-work.svg' ), 'url' => home_url( '/services/integrations-automation/' ), 'details' => array( 'Webhooks', 'APIs', 'CRM sync', 'Reporting' ) ), array( 'key' => 'care', 'title' => __( 'Website Care & Support', 'nolan-young-theme-template-01' ), 'description' => __( 'Keep the site healthy with updates, monitoring, and steady improvements.', 'nolan-young-theme-template-01' ), 'image' => nytt01_get_navigation_image_uri( 'meet-the-team.svg' ), 'url' => home_url( '/services/website-care-support/' ), 'details' => array( 'Updates', 'Backups', 'Monitoring', 'Support' ) ) ); return apply_filters( 'nytt01_services_mega_menu_items', $items ); }
function nytt01_get_about_mega_menu_items() { $items = array( array( 'key' => 'approach', 'title' => __( 'Our Approach', 'nolan-young-theme-template-01' ), 'description' => __( 'Strategy, design, and engineering are kept in one clear delivery system.', 'nolan-young-theme-template-01' ), 'image' => nytt01_get_navigation_image_uri( 'about-us.svg' ), 'url' => home_url( '/about/#approach' ), 'details' => array( 'Discovery first', 'Tight scope', 'Accessible by default', 'Iterative reviews' ) ), array( 'key' => 'values', 'title' => __( 'What We Value', 'nolan-young-theme-template-01' ), 'description' => __( 'Clarity, craft, maintainability, and honest communication guide decisions.', 'nolan-young-theme-template-01' ), 'image' => nytt01_get_navigation_image_uri( 'careers.svg' ), 'url' => home_url( '/about/#values' ), 'details' => array( 'Clarity', 'Craft', 'Reliability', 'Respect for time' ) ), array( 'key' => 'work', 'title' => __( 'How We Work', 'nolan-young-theme-template-01' ), 'description' => __( 'Short feedback loops, explicit milestones, and practical handoff support.', 'nolan-young-theme-template-01' ), 'image' => nytt01_get_navigation_image_uri( 'future-work.svg' ), 'url' => home_url( '/about/#work' ), 'details' => array( 'Milestones', 'Review gates', 'Docs', 'Launch support' ) ) ); return apply_filters( 'nytt01_about_mega_menu_items', $items ); }
function nytt01_get_mega_menu_markup( $mega_key, $panel_id, $trigger_id, $menu_item ) { ob_start(); if ( 'blog' === $mega_key ) { get_template_part( 'template-parts/header/mega-menu', 'blog', array( 'panel_id' => $panel_id, 'trigger_id' => $trigger_id, 'overview_url' => ! empty( $menu_item->url ) ? $menu_item->url : home_url( '/blog/' ) ) ); } else { get_template_part( 'template-parts/header/mega-menu', 'featured', array( 'mega_key' => $mega_key, 'panel_id' => $panel_id, 'trigger_id' => $trigger_id, 'overview_url' => ! empty( $menu_item->url ) ? $menu_item->url : home_url( '/' ), 'items' => 'services' === $mega_key ? nytt01_get_services_mega_menu_items() : nytt01_get_about_mega_menu_items() ) ); } return (string) ob_get_clean(); }
class NYTT01_Primary_Nav_Walker extends Walker_Nav_Menu { public function start_el( &$output, $menu_item, $depth = 0, $args = null, $id = 0 ) { $mega_key = 0 === $depth ? nytt01_get_mega_menu_key( $menu_item ) : ''; if ( '' === $mega_key ) { parent::start_el( $output, $menu_item, $depth, $args, $id ); return; } $panel_id = 'services' === $mega_key || 'about' === $mega_key ? $mega_key . '-menu' : 'blog-menu'; $trigger_id = $panel_id . '-trigger-' . (int) $menu_item->ID; $classes = array_filter( (array) $menu_item->classes ); $classes[] = 'nytt01-menu-item--mega'; $output .= '<li class="' . esc_attr( implode( ' ', array_map( 'sanitize_html_class', array_unique( $classes ) ) ) ) . '" data-menu-item="' . esc_attr( $mega_key ) . '">'; $output .= '<button type="button" class="nytt01-menu__trigger" aria-expanded="false" aria-controls="' . esc_attr( $panel_id ) . '" data-menu-item="' . esc_attr( $mega_key ) . '">' . esc_html( apply_filters( 'the_title', $menu_item->title, $menu_item->ID ) ) . '</button>'; $output .= nytt01_get_mega_menu_markup( $mega_key, $panel_id, $trigger_id, $menu_item ); } }
